require __DIR__.'/config/database.php';function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$rows=$pdo->query("SELECT sv.ma_sv,sv.ho_ten,hp.ma_hoc_phan,hp.ten_hoc_phan,ct.ngay_thi,dk.so_bao_danh,kq.tinh_trang,kq.diem_thi,kq.diem_bi_tru,kq.da_huy_ket_qua FROM ket_qua_thi kq JOIN dang_ky_thi dk ON dk.id=kq.dang_ky_thi_id JOIN sinh_vien sv ON sv.id=dk.sinh_vien_id JOIN hoc_phan hp ON hp.id=dk.hoc_phan_id JOIN ca_thi ct ON ct.id=dk.ca_thi_id ORDER BY ct.ngay_thi DESC,sv.ma_sv LIMIT 500")->fetchAll();
